const escapeText = (value) => String(value).replace(/[&<>"']/g, (character) => ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'}[character]));

function timeline(items, label, illustration = '') {
    return `<pics-horizontal-timeline class="u2-timeline" aria-label="${label}"><ol class="pics-horizontal-timeline__events" data-timeline-events>${items.map((item, index) => `<li data-timeline-event data-label="${escapeText(item.label)}"><article><p class="u2-timeline__index">${String(index + 1).padStart(2, '0')}</p><h4>${escapeText(item.label)}</h4><p>${escapeText(item.detail)}</p>${index === 0 ? illustration : ''}</article></li>`).join('')}</ol></pics-horizontal-timeline>`;
}

function riskDetails() {
    return `<div class="u2-details">${RISKS.map((risk) => `<details open><summary>${escapeText(risk.title)}</summary><p>${escapeText(risk.detail)}</p></details>`).join('')}</div>`;
}

function lianGongParts() {
    return `<div class="u2-parts">${LIAN_GONG_CARDS.map((card, index) => `<details><summary><span class="u2-parts__number" aria-hidden="true">0${index + 1}</span><span><span class="u2-parts__part">${escapeText(card.part)}</span><strong>${escapeText(card.title)}</strong><span class="u2-parts__hint">Clique para ver os detalhes ↻</span></span></summary><p>${escapeText(card.detail)}</p></details>`).join('')}</div>`;
}

function communityActions() {
    return `<details class="u2-actions"><summary>Ver atividades que os ACS/ACE podem realizar</summary><ul>${ACS_ACTIONS.map((action) => `<li>${escapeText(action)}</li>`).join('')}</ul></details>`;
}

