function referenceLibrary() {
    return `<div class="u2-library">${REF_CATEGORIES.map((category) => `<details open><summary><span class="u2-library__category">${escapeText(category.title)}</span><span class="u2-library__count">${category.docs.length} documentos</span></summary><p class="u2-library__description">${escapeText(category.description)}</p><div>${category.docs.map((document, index) => `<article class="u2-library__document"><span class="u2-library__number" aria-hidden="true">0${index + 1}</span><div><p class="u2-library__type">${escapeText(document.type)} · ${escapeText(document.year)}</p><h3>${escapeText(document.title)}</h3><p class="u2-library__source">${escapeText(document.source)}</p><p>${escapeText(document.description)}</p><div class="u2-library__links"><a class="u2-document-link" href="${escapeText(document.file)}" download>⬇ Baixar PDF</a><a class="u2-related-link" href="#/unidade/unidade-2/pagina/${referencePages[document.anchor]}" data-reading-destination="${document.anchor.slice(1)}">↳ ${escapeText(document.anchorLabel)}</a></div></div></article>`).join('')}</div></details>`).join('')}</div>`;
}

